### 2. .NET Implementation (Using `Microsoft.Extensions.AI`)

The .NET version of the Agent Framework is built directly on top of the **`Microsoft.Extensions.AI`** ecosystem. It uses `IChatClient` as its core abstraction. 

To implement failover in .NET, you can create a custom **`DelegatingChatClient`** (or a class implementing `IChatClient`) that wraps a primary and a secondary client. If the primary client throws an exception, the delegating client catches it and forwards the request to the backup client.

#### How it works:
* Create a `FailoverChatClient` that implements `IChatClient`.
* In `GetResponseAsync` and `GetStreamingResponseAsync`, wrap the primary call in a `try-catch` block.
* On failure, fall back to the secondary client.

#### Code Example:
```csharp
using System;
using System.Collections.Generic;
using System.Runtime.CompilerServices;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.AI;
using Microsoft.Agents.AI;

namespace FailoverSample
{
    public class FailoverChatClient : IChatClient
    {
        private readonly IChatClient _primary;
        private readonly IChatClient _backup;

        public FailoverChatClient(IChatClient primary, IChatClient backup)
        {
            _primary = primary ?? throw new ArgumentNullException(nameof(primary));
            _backup = backup ?? throw new ArgumentNullException(nameof(backup));
        }

        public ChatClientMetadata Metadata => _primary.Metadata;

        public async Task<ChatResponse> GetResponseAsync(
            IList<ChatMessage> chatMessages,
            ChatOptions? options = null,
            CancellationToken cancellationToken = default)
        {
            try
            {
                // Attempt primary client
                return await _primary.GetResponseAsync(chatMessages, options, cancellationToken);
            }
            catch (Exception ex)
            {
                Console.WriteLine($"[Warning] Primary client failed: {ex.Message}. Failing over to backup...");

                // Fallback to backup client
                return await _backup.GetResponseAsync(chatMessages, options, cancellationToken);
            }
        }

        public async IAsyncEnumerable<StreamingChatResponseUpdate> GetStreamingResponseAsync(
            IList<ChatMessage> chatMessages,
            ChatOptions? options = null,
            [EnumeratorCancellation] CancellationToken cancellationToken = default)
        {
            IAsyncEnumerator<StreamingChatResponseUpdate>? enumerator = null;
            bool primaryFailed = false;

            try
            {
                enumerator = _primary.GetStreamingResponseAsync(chatMessages, options, cancellationToken)
                                     .GetAsyncEnumerator(cancellationToken);
            }
            catch
            {
                primaryFailed = true;
            }

            if (!primaryFailed && enumerator != null)
            {
                while (true)
                {
                    StreamingChatResponseUpdate? current = null;
                    try
                    {
                        if (!await enumerator.MoveNextAsync()) break;
                        current = enumerator.Current;
                    }
                    catch (Exception ex)
                    {
                        Console.WriteLine($"[Warning] Primary stream failed mid-flight: {ex.Message}. Failing over to backup...");
                        primaryFailed = true;
                    }

                    if (primaryFailed) break;
                    if (current != null) yield return current;
                }
            }

            if (primaryFailed)
            {
                // Fallback to backup client stream
                await foreach (var update in _backup.GetStreamingResponseAsync(chatMessages, options, cancellationToken))
                {
                    yield return update;
                }
            }
        }

        public object? GetService(Type serviceType, object? serviceKey = null)
        {
            return _primary.GetService(serviceType, serviceKey) ?? _backup.GetService(serviceType, serviceKey);
        }

        public void Dispose()
        {
            _primary.Dispose();
            _backup.Dispose();
        }
    }
}
```

#### Registering the Failover Client on the Agent:
```csharp
using Azure.Identity;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;

// 1. Create your primary and backup clients
IChatClient primaryClient = new AzureOpenAIClient(
    new Uri("https://your-primary.openai.azure.com/"), 
    new DefaultAzureCredential()
).AsIChatClient("gpt-4o");

IChatClient backupClient = new OpenAIClient(
    "your-backup-api-key"
).AsIChatClient("gpt-4o-mini");

// 2. Wrap them in your FailoverChatClient
IChatClient resilientClient = new FailoverChatClient(primaryClient, backupClient);

// 3. Build the AIAgent using the resilient client
AIAgent agent = resilientClient.AsAIAgent(
    name: "ResilientAgent",
    instructions: "You are a highly available assistant."
);
```

